<?php use App\Domain\Deliveries\DeliveryRules as Rules; ?>
<div class="deliveries-workspace"><section class="admin-page-head"><div><p class="admin-kicker">LOGÍSTICA Y ENTREGAS</p><h1>Entregas</h1><p>Organiza la preparación, el despacho y la recepción de mercancía por el cliente.</p></div><div class="admin-head-actions"><?php if($canCreate):?><a class="admin-primary-button" data-admin-form-link href="/admin/deliveries/create">+ Crear entrega</a><?php endif?><?php if($canResources):?><a class="admin-secondary-button" data-admin-form-link href="/admin/deliveries/resources">Vehículos, repartidores y rutas</a><?php endif?></div></section>
<section class="deliveries-guide" aria-label="Proceso de entrega"><div><span>01</span><div><h2>Programa y prepara</h2><p>Selecciona una cotización aceptada y las cantidades que se entregarán.</p></div></div><div><span>02</span><div><h2>Asigna y despacha</h2><p>Organiza la salida y confirma la mercancía que sale físicamente.</p></div></div><div><span>03</span><div><h2>Confirma la recepción</h2><p>Registra lo recibido por el cliente y conserva el seguimiento de lo pendiente.</p></div></div></section><section class="admin-panel deliveries-filters"><header><h2>Buscar entregas</h2><p>Consulta el avance por folio, cotización, cliente o sucursal.</p></header><form class="deliveries-filter-grid" method="get" action="/admin/deliveries"><label class="admin-field"><span>Folio, cotización o cliente</span><input type="search" placeholder="Folio, cotización o nombre del cliente" name="q" value="<?= e($q) ?>" maxlength="120"></label><label class="admin-field"><span>Sucursal</span><select name="branch_id"><option value="">Todas autorizadas</option><?php foreach($branches as $b):?><option value="<?= e($b['id']) ?>" <?= $branchId===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Estado</span><select name="status"><option value="">Todos</option><?php foreach(Rules::LABELS as $key=>$label):?><option value="<?= e($key) ?>" <?= $status===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach?></select></label><div class="deliveries-filter-actions"><button class="admin-secondary-button">Aplicar filtros</button><?php if($q!==''||$status!==''||$branchId):?><a class="deliveries-text-link" href="/admin/deliveries">Limpiar</a><?php endif?></div></form></section>
<section class="admin-panel admin-table-panel deliveries-directory"><header class="deliveries-directory-heading"><div><h2>Entregas registradas</h2><p>Documento relacionado, responsable y avance de recepción.</p></div><span><?= e(count($page->items)) ?> en esta página</span></header><?php if(!$page->items):?><div class="deliveries-empty"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h11v11H3V6Zm11 4h4l3 4v3h-7M6 17a2 2 0 1 0 0 4 2 2 0 0 0 0-4Zm12 0a2 2 0 1 0 0 4 2 2 0 0 0 0-4Z"/></svg><h3><?= ($q!==''||$status!==''||$branchId)?'Sin coincidencias':'Aún no hay entregas registradas' ?></h3><p><?= ($q!==''||$status!==''||$branchId)?'Prueba con otro folio, cliente, sucursal o estado, o limpia los filtros.':'Comienza con una cotización aceptada. Podrás programar la entrega, preparar la mercancía y registrar su recepción.' ?></p><div class="deliveries-empty-actions"><?php if($q!==''||$status!==''||$branchId):?><a class="admin-secondary-button" href="/admin/deliveries">Limpiar filtros</a><?php elseif($canCreate):?><a class="admin-primary-button" data-admin-form-link href="/admin/deliveries/create">Crear primera entrega</a><?php endif?></div></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Folio / fecha</th><th>Cliente / documento</th><th>Sucursal</th><th>Estado</th><th>Responsable</th><th>Partidas recibidas</th><th>Acciones</th></tr></thead><tbody><?php foreach($page->items as $t):?><tr><td data-label="Folio / fecha"><div><?= e($t['folio']) ?><small><?= e($t['created_at']) ?> UTC</small></div></td><td data-label="Cliente / documento"><div><?= e($t['customer_name']) ?><small><?= e($t['quote_folio']) ?></small></div></td><td data-label="Sucursal"><?= e($t['branch_name']) ?></td><td data-label="Estado"><span class="deliveries-status" data-state="<?= e($t['status']) ?>"><?= e(Rules::LABELS[$t['status']]) ?></span></td><td data-label="Responsable"><?= e($t['actor_name']) ?></td><td data-label="Partidas"><?= e($t['completed_items'].' / '.$t['item_count']) ?></td><td class="admin-actions"><a class="admin-secondary-button" data-admin-form-link href="/admin/deliveries/detail?id=<?= e($t['id']) ?>">Abrir</a></td></tr><?php endforeach?></tbody></table></div><?php endif?><?php if($page->offset>0||$page->hasMore):?><nav class="admin-pagination" aria-label="Paginación"><?php $params=['q'=>$q,'status'=>$status,'branch_id'=>$branchId];if($page->offset>0):?><a href="?<?= e(http_build_query($params+['offset'=>max(0,$page->offset-25)])) ?>">Anterior</a><?php endif?><?php if($page->hasMore):?><a href="?<?= e(http_build_query($params+['offset'=>$page->offset+25])) ?>">Siguiente</a><?php endif?></nav><?php endif?></section></div>
